CREATE DATABASE habotconnect;
\c habotconnect;
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,name VARCHAR(120));
CREATE TABLE IF NOT EXISTS parents(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE NOT NULL REFERENCES users(id),phone VARCHAR(30),address VARCHAR(255));
CREATE TABLE IF NOT EXISTS students(id BIGSERIAL PRIMARY KEY,parent_id BIGINT NOT NULL REFERENCES parents(id),name VARCHAR(120) NOT NULL,age INT,grade VARCHAR(50),learning_difficulty VARCHAR(120),location VARCHAR(120),notes TEXT,predecessor_id BIGINT REFERENCES students(id));
CREATE TABLE IF NOT EXISTS lsa_profiles(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE NOT NULL REFERENCES users(id),specialization VARCHAR(120),experience_years INT,location VARCHAR(120),bio TEXT,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS availability(id BIGSERIAL PRIMARY KEY,lsa_id BIGINT NOT NULL REFERENCES lsa_profiles(id),day_of_week VARCHAR(20),start_time VARCHAR(10),end_time VARCHAR(10),available BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS matching_requests(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES students(id),parent_id BIGINT NOT NULL REFERENCES parents(id),preferred_specialization VARCHAR(120),status VARCHAR(30) DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS matches(id BIGSERIAL PRIMARY KEY,student_id BIGINT UNIQUE NOT NULL REFERENCES students(id),lsa_id BIGINT NOT NULL REFERENCES lsa_profiles(id),request_id BIGINT UNIQUE NOT NULL REFERENCES matching_requests(id),status VARCHAR(30) DEFAULT 'ACTIVE',score INT,matched_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES students(id),lsa_id BIGINT NOT NULL REFERENCES lsa_profiles(id),scheduled_at TIMESTAMP,status VARCHAR(30) DEFAULT 'SCHEDULED',notes TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,user_id BIGINT,action VARCHAR(100),entity_name VARCHAR(100),entity_id BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
